#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic<int> completed{0};
    std::jthread a([&] { completed.fetch_add(1); });
    std::jthread b([&] { completed.fetch_add(1); });
    a.join(); b.join();
    std::cout << completed.load() << '\n';
}
